def compare_versions(a: str, b: str) -> int:
    """Compare two Semantic Versioning 2.0.0 strings.

    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    """
    def split_parts(v: str):
        # Remove build metadata
        v, *_ = v.split("+", 1)
        # Separate pre-release
        if "-" in v:
            core, pre = v.split("-", 1)
            pre_ids = pre.split(".")
        else:
            core = v
            pre_ids = []
        major, minor, patch = map(int, core.split("."))
        return major, minor, patch, pre_ids

    def compare_ids(a_ids, b_ids):
        """Compare two pre-release identifier lists.
        Returns -1,0,1 according to SemVer rules."""
        for a_id, b_id in zip(a_ids, b_ids):
            a_isnum = a_id.isdigit()
            b_isnum = b_id.isdigit()
            if a_isnum and b_isnum:
                a_num = int(a_id)
                b_num = int(b_id)
                if a_num < b_num:
                    return -1
                if a_num > b_num:
                    return 1
            elif a_isnum and not b_isnum:
                return -1
            elif not a_isnum and b_isnum:
                return 1
            else:
                if a_id < b_id:
                    return -1
                if a_id > b_id:
                    return 1
        # All compared identifiers are equal so far
        if len(a_ids) < len(b_ids):
            return -1
        if len(a_ids) > len(b_ids):
            return 1
        return 0

    a_major, a_minor, a_patch, a_pre = split_parts(a)
    b_major, b_minor, b_patch, b_pre = split_parts(b)

    # Compare core version numbers
    if a_major != b_major:
        return -1 if a_major < b_major else 1
    if a_minor != b_minor:
        return -1 if a_minor < b_minor else 1
    if a_patch != b_patch:
        return -1 if a_patch < b_patch else 1

    # At this point core versions are equal
    if not a_pre and not b_pre:
        return 0
    if not a_pre:
        return 1  # a has no pre-release => higher
    if not b_pre:
        return -1  # b has no pre-release => higher

    return compare_ids(a_pre, b_pre)
